        "script": "var raw = $vars.start.output.invoiceNumber;\nvar normalized = (raw || '').trim().toUpperCase();\nif (!normalized.startsWith('MCS-')) {\n  normalized = 'MCS-' + normalized;\n}\nreturn { normalizedNumber: normalized };"
